-- PT107-S4-Q6. Batch 10.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch10$PT107-S4-Q6$batch10$ AND q.stimulus=$batch10$Some judges complain about statutes that specify mandatory minimum sentences for criminal offenses. These legal restrictions, they complain, are too mechanical and prevent judges from deciding when a given individual can or cannot be rehabilitated. But that is precisely why mandatory minimum sentences are necessary. History amply demonstrates that when people are free to use their own judgment they invariably believe themselves to act wisely when in fact they are often arbitrary and irrational. There is no reason to think that judges are an exception to this rule.$batch10$ AND q.prompt=$batch10$Which one of the following sentences most accurately expresses the main point of the passage?$batch10$ AND q.correct_choice=$batch10$E$batch10$) THEN RAISE EXCEPTION 'Question changed: PT107-S4-Q6'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch10$PT107-S4-Q6$batch10$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT107-S4-Q6'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch10$PT107-S4-Q6$batch10$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch10$Opposing Point$batch10$, $batch10$Some judges complain that mandatory minimum sentences are too mechanical and stop judges from deciding who can be rehabilitated.$batch10$), (1, $batch10$Conclusion$batch10$, $batch10$That is exactly why mandatory minimum sentences are necessary.$batch10$), (2, $batch10$Evidence$batch10$, $batch10$People free to use their own judgment think they act wisely but are often arbitrary and irrational, and judges are no exception.$batch10$), (3, $batch10$Evaluate$batch10$, $batch10$"But that is precisely why" marks the pivot. Swap "that" for what it refers to: minimums are necessary because they limit judges' discretion. The last two sentences explain why limiting discretion is good: judges' judgment is often arbitrary.$batch10$), (4, $batch10$Goal$batch10$, $batch10$Mandatory minimum sentences are needed because they keep judges from acting arbitrarily.$batch10$)) v(position,label,body) WHERE q.qid=$batch10$PT107-S4-Q6$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch10$A$batch10$, $batch10$This is a distorted version of the evidence. The passage says people are often arbitrary, not that they never have good judgment.$batch10$), ($batch10$B$batch10$, $batch10$This is the judges' complaint, which the author is answering.$batch10$), ($batch10$C$batch10$, $batch10$The author argues that judges' discretion should be limited.$batch10$), ($batch10$D$batch10$, $batch10$This is the support for the conclusion. Judges being often arbitrary is why minimums are needed.$batch10$), ($batch10$E$batch10$, $batch10$Minimums are necessary, and the reason is to limit arbitrary judicial discretion. This combines the pivot sentence with what "that" refers to.$batch10$)) v(letter,body) WHERE q.qid=$batch10$PT107-S4-Q6$batch10$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
